def add_flight_stubs(stubs):
    stubs['net/minecraft/util/math/AxisAlignedBB.java'] = '''package net.minecraft.util.math; public class AxisAlignedBB { public final double minX,minY,minZ,maxX,maxY,maxZ; public AxisAlignedBB(double a,double b,double c,double d,double e,double f){minX=a;minY=b;minZ=c;maxX=d;maxY=e;maxZ=f;} public AxisAlignedBB expand(double x,double y,double z){return new AxisAlignedBB(minX+Math.min(0,x),minY+Math.min(0,y),minZ+Math.min(0,z),maxX+Math.max(0,x),maxY+Math.max(0,y),maxZ+Math.max(0,z));} public boolean intersects(AxisAlignedBB b){return maxX>b.minX && minX<b.maxX && maxY>b.minY && minY<b.maxY && maxZ>b.minZ && minZ<b.maxZ;} }'''
    stubs['net/minecraft/world/World.java'] = '''package net.minecraft.world; import java.util.*; import net.minecraft.entity.Entity; import net.minecraft.util.math.*; public class World { public boolean isRemote=false, loaded=true; public int checks,queries,height=256; public java.util.List<AxisAlignedBB> liquids=new java.util.ArrayList<>(); public boolean containsAnyLiquid(AxisAlignedBB box){if(!loaded)throw new AssertionError("liquid queried unloaded"); queries++; for(AxisAlignedBB b:liquids)if(box.intersects(b))return true; return false;} public List<AxisAlignedBB> obstacles=new ArrayList<>(); public boolean isAreaLoaded(BlockPos p,int n){checks++; return loaded;} public int getActualHeight(){return height;} public List<AxisAlignedBB> getCollisionBoxes(Entity e,AxisAlignedBB box){if(!loaded)throw new AssertionError("queried unloaded"); queries++; List<AxisAlignedBB> r=new ArrayList<>(); for(AxisAlignedBB b:obstacles)if(box.intersects(b))r.add(b); return r;} }'''
    stubs['net/minecraft/entity/EntityCreature.java'] = stubs['net/minecraft/entity/EntityCreature.java'].replace('protected boolean isImmuneToFire;', '''protected boolean isImmuneToFire; public boolean onGround=true, water=false, lava=false, riding=false, ridden=false, noAI=false; public float fallDistance; public int falls; public boolean isAIDisabled(){return noAI;} public void onLivingUpdate(){} public boolean isInWater(){return water;} public boolean isInLava(){if(!world.loaded)throw new AssertionError("lava queried unloaded"); return lava;} public boolean isRiding(){return riding;} public boolean isBeingRidden(){return ridden;} public net.minecraft.util.math.AxisAlignedBB getEntityBoundingBox(){return new net.minecraft.util.math.AxisAlignedBB(posX-1.4,posY,posZ-1.4,posX+1.4,posY+3.4,posZ+1.4);} public Move getMoveHelper(){return new Move();} public static class Move {public void setMoveTo(double x,double y,double z,double s){}}''').replace('public void fall(float a,float b){}', 'public void fall(float a,float b){falls++;}')
    stubs['net/minecraft/nbt/NBTTagCompound.java'] = stubs['net/minecraft/nbt/NBTTagCompound.java'].replace('public int getInteger(String s)', 'public void setBoolean(String s,boolean b){setInteger(s,b?1:0);} public boolean getBoolean(String s){return getInteger(s)!=0;} public int getInteger(String s)')
